parameters.jsCode:
const crypto = require('crypto');

return items
  .map((item) => {
    const j = item.json || {};
    const url = j.link || j.url || j.guid;
    if (!url) return null;
    const hash = crypto.createHash('sha256').update(url).digest('hex');
    return {
      json: {
        source_url: url,
        url_hash: hash,
        title: j.title || '(无标题)',
        author: j.creator || j.author || null,
        published_at: j.pubDate || j.isoDate || null,
        raw_html: j['content:encoded'] || j.content || j.description || '',
        language: 'zh-CN'
      }
    };
  })
  .filter(Boolean);

