INSERT INTO intel.articles_vault (
  source_url, url_hash, title, author, published_at, raw_html, language, status
) VALUES (
  $1, $2, $3, $4, $5::timestamptz, $6, $7, 'NEW'
)
ON CONFLICT (url_hash) DO NOTHING
RETURNING article_id;
